// Production-rate and job-pricing arithmetic for a forestry mulching or land
// clearing job.
//
// Everything here is deterministic. There is no model, no lookup service, no
// market rate table and no network call: the output is a price an operator
// puts in front of a landowner and then has to clear the ground for, so every
// figure has to be re-derivable on paper from numbers they typed.
//
// The modelling choice the whole tool rests on, stated up front:
//
//   **Price per acre is an output, not an input.** The trade quotes in
//   dollars per acre and then reasons in dollars per acre, but the machine
//   is paid for by the hour. What converts one to the other is the
//   *production rate* -- acres per machine-hour -- and that rate is not a
//   property of the job's acreage. It is a property of what is standing on
//   it. So this computes hours first, from head width, advance speed and
//   pass count, and reports the per-acre figure last, as the quotient it
//   actually is.
//
// The advance-speed and pass-count presets below are starting points a
// specific operator is expected to overwrite with their own numbers, and the
// page keeps them visible and editable for exactly that reason. They are not
// survey data and this file does not pretend they are: see DENSITY_CLASSES.

/** Square feet in an acre. Exact, by definition (66 ft x 660 ft). */
export const SQ_FT_PER_ACRE = 43560;

/**
 * Starting points for the four density descriptions a mulching customer
 * actually gives over the phone, in the trade's own words.
 *
 * `advanceFtPerMin` is how fast the machine moves *forward while cutting*, not
 * its travel speed. `passes` is how many times the same ground is worked: on
 * light material the mat falls small enough on the first pass, and on heavy
 * material the standing stems come down first and the mat is then reworked to
 * get the particle size down to something a customer calls finished.
 *
 * **These are defaults to argue with, not a rate card.** Real production
 * varies with the head, the carrier's horsepower, hydraulic flow, the species
 * mix, moisture and the operator, and it varies by more than the difference
 * between two of these rows. An operator who has timed themselves on one job
 * should type that rate in instead -- `acresPerHourFrom` below is exposed so
 * the page can show them what their own timing implies, and
 * `advanceSpeedForAcresPerHour` inverts it so they can enter the rate directly.
 */
export const DENSITY_CLASSES = {
  'light-brush': {
    label: 'Light brush, grass and saplings under 2 in',
    advanceFtPerMin: 90,
    passes: 1,
    note: 'Fence lines, old pasture growing back in, a trail corridor kept up.',
  },
  'medium-brush': {
    label: 'Medium brush, stems 2-4 in with the odd 6 in',
    advanceFtPerMin: 42,
    passes: 1,
    note: 'The most commonly quoted job: a lot that has been idle five to ten years.',
  },
  'heavy-brush': {
    label: 'Heavy brush and small trees, stems 4-8 in',
    advanceFtPerMin: 40,
    passes: 2,
    note: 'Standing stems come down on the first pass and the mat is reworked on the second.',
  },
  'heavy-timber': {
    label: 'Heavy understory, stems 8-12 in',
    advanceFtPerMin: 30,
    passes: 3,
    note: 'Slow going, hard on teeth, and the class most often quoted at a medium-brush price.',
  },
};

/**
 * Money, with the sign outside the symbol.
 *
 * `-$9.24`, never `$-9.24`; and a value that rounds to zero prints `$0.00`
 * rather than `-$0.00`, which is a break-even line claiming to be down money.
 * See platform/ci/check_money_sign.py for why this is spelled out in every
 * venture rather than shared.
 */
export function money(value) {
  const rounded = Math.round((Number(value) + Number.EPSILON) * 100) / 100;
  const safe = Object.is(rounded, -0) ? 0 : rounded;
  const body = Math.abs(safe).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  return `${safe < 0 ? '-' : ''}$${body}`;
}

function requireFinite(value, label, { min, max, integer = false } = {}) {
  // `Number(null)` and `Number('')` are both 0, and 0 clears most of the
  // floors below. A blank operator wage, fuel price or tooth cost would then
  // price the machine at nothing an hour and report a healthy margin on it,
  // which is the quietest way this worksheet could be wrong. Absent is
  // refused before it can become zero.
  if (value === null || value === undefined || value === '') {
    throw new RangeError(`${label} must be a number`);
  }
  const n = Number(value);
  if (!Number.isFinite(n)) throw new RangeError(`${label} must be a number`);
  if (integer && !Number.isInteger(n)) throw new RangeError(`${label} must be a whole number`);
  if (min !== undefined && n < min) throw new RangeError(`${label} must be at least ${min}`);
  if (max !== undefined && n > max) throw new RangeError(`${label} must be at most ${max}`);
  return n;
}

/**
 * Acres cut per hour on the clock, from the geometry of the cut.
 *
 *   swath (ft) x advance (ft/min) x 60 min  =  square feet cut per hour
 *
 * divided by passes over the same ground, and by the acre, and multiplied by
 * the share of the hour the machine is actually cutting rather than
 * repositioning, refuelling, checking teeth or walking a boundary.
 *
 * `terrainFactorPct` divides the advance speed: 100 is the flat, open, dry
 * ground the speed was quoted on, and anything below it is slope, rock,
 * standing water, stumps to steer around or a boundary too tight to run long
 * lines in.
 */
export function acresPerHourFrom({
  headWidthFt,
  advanceFtPerMin,
  passes,
  cuttingEfficiencyPct,
  terrainFactorPct,
}) {
  const width = requireFinite(headWidthFt, 'Mulching head width', { min: 1, max: 20 });
  const advance = requireFinite(advanceFtPerMin, 'Advance speed', { min: 1, max: 400 });
  const pass = requireFinite(passes, 'Passes over the ground', { min: 1, max: 6 });
  const efficiency = requireFinite(cuttingEfficiencyPct, 'Share of the hour cutting', { min: 5, max: 100 });
  const terrain = requireFinite(terrainFactorPct, 'Terrain factor', { min: 10, max: 100 });

  const effectiveAdvance = advance * (terrain / 100);
  const sqFtPerHour = width * effectiveAdvance * 60 * (efficiency / 100);
  return sqFtPerHour / SQ_FT_PER_ACRE / pass;
}

/**
 * The inverse: the advance speed implied by a production rate an operator has
 * actually timed on a job of their own.
 *
 * This is the honest direction of travel for anybody who has a stopwatch and a
 * finished lot, and it is why the presets above are not load-bearing. Given
 * "three quarters of an acre in four hours" they get the speed that produces
 * it, on their own head width, and can see whether the number is plausible.
 */
export function advanceSpeedForAcresPerHour({
  headWidthFt,
  acresPerHour,
  passes,
  cuttingEfficiencyPct,
  terrainFactorPct,
}) {
  const width = requireFinite(headWidthFt, 'Mulching head width', { min: 1, max: 20 });
  const rate = requireFinite(acresPerHour, 'Production rate', { min: 0.001, max: 20 });
  const pass = requireFinite(passes, 'Passes over the ground', { min: 1, max: 6 });
  const efficiency = requireFinite(cuttingEfficiencyPct, 'Share of the hour cutting', { min: 5, max: 100 });
  const terrain = requireFinite(terrainFactorPct, 'Terrain factor', { min: 10, max: 100 });

  const sqFtPerHour = rate * SQ_FT_PER_ACRE * pass;
  return sqFtPerHour / (width * 60 * (efficiency / 100) * (terrain / 100));
}

/**
 * What one hour of this machine costs before any profit is added.
 *
 * Five lines, and the two that go missing from a hand-written quote are the
 * last two.
 *
 * **Teeth.** Carbide tools are a consumable, not a repair. A full set on a
 * drum head is a four-figure item and it is consumed over hundreds of hours,
 * faster in sand and rock. Spread over the hours it lasts it is a real and
 * sizeable cost per hour; left out of the quote it is an invoice that arrives
 * later with no job attached to it.
 *
 * **Ownership.** The payment and the insurance are owed every month whether
 * the machine turns or not, so the burden *per hour* is set by how many hours
 * a month it actually bills. That is the number an operator is most likely to
 * flatter themselves about, and it moves the per-hour cost more than fuel
 * does: the same payment over 40 billable hours costs four times what it does
 * over 160.
 */
export function machineCostPerHour(input) {
  const {
    operatorWagePerHour,
    fuelGallonsPerHour,
    fuelPricePerGallon,
    toothSetCost,
    toothSetLifeHours,
    maintenancePerHour,
    machinePaymentMonthly,
    insuranceAnnual,
    billableHoursPerMonth,
  } = input;

  const wage = requireFinite(operatorWagePerHour, 'Operator cost', { min: 0, max: 500 });
  const gph = requireFinite(fuelGallonsPerHour, 'Fuel burn', { min: 0, max: 60 });
  const fuelPrice = requireFinite(fuelPricePerGallon, 'Fuel price', { min: 0, max: 30 });
  const teethCost = requireFinite(toothSetCost, 'Cost of a set of teeth', { min: 0, max: 20000 });
  const teethLife = requireFinite(toothSetLifeHours, 'Hours a set of teeth lasts', { min: 1, max: 5000 });
  const maintenance = requireFinite(maintenancePerHour, 'Service and repair reserve', { min: 0, max: 500 });
  const payment = requireFinite(machinePaymentMonthly, 'Machine payment', { min: 0, max: 100000 });
  const insurance = requireFinite(insuranceAnnual, 'Insurance', { min: 0, max: 200000 });
  const billableHours = requireFinite(billableHoursPerMonth, 'Billable hours a month', { min: 1, max: 730 });

  const fuel = gph * fuelPrice;
  const teeth = teethCost / teethLife;
  const ownership = (payment + insurance / 12) / billableHours;

  return {
    operator: wage,
    fuel,
    teeth,
    maintenance,
    ownership,
    total: wage + fuel + teeth + maintenance + ownership,
  };
}

/**
 * The whole job: hours, days, cost, and the price that clears a margin.
 *
 * Margin is taken on the *price*, not as a markup on cost:
 * `price = cost / (1 - margin)`. A 40% margin means $40 of every $100
 * invoiced, which is what an operator means by it, and it is not the same as
 * adding 40% to cost.
 *
 * Mobilization is kept out of the hourly cost and added as its own line,
 * because it does not scale with acreage and that is the entire reason small
 * jobs lose money. One `mobilizationTrips` is one round trip with the machine
 * on the trailer -- out and back.
 */
export function priceJob(input) {
  const {
    acres,
    headWidthFt,
    advanceFtPerMin,
    passes,
    cuttingEfficiencyPct,
    terrainFactorPct,
    workHoursPerDay,
    mobilizationTrips,
    mobilizationHoursEach,
    mobilizationMilesEach,
    truckCostPerMile,
    otherCosts,
    targetMarginPct,
  } = input;

  const area = requireFinite(acres, 'Acres to clear', { min: 0.05, max: 5000 });
  const hoursPerDay = requireFinite(workHoursPerDay, 'Machine hours a day', { min: 1, max: 24 });
  const trips = requireFinite(mobilizationTrips, 'Mobilization trips', { min: 0, max: 40, integer: true });
  const mobHours = requireFinite(mobilizationHoursEach, 'Hours per mobilization', { min: 0, max: 48 });
  const mobMiles = requireFinite(mobilizationMilesEach, 'Miles per mobilization', { min: 0, max: 3000 });
  const perMile = requireFinite(truckCostPerMile, 'Truck and trailer cost', { min: 0, max: 30 });
  const other = requireFinite(otherCosts, 'Other job costs', { min: 0, max: 1000000 });
  const margin = requireFinite(targetMarginPct, 'Target margin', { min: 0, max: 95 });

  const rate = machineCostPerHour(input);
  const acresPerHour = acresPerHourFrom({
    headWidthFt,
    advanceFtPerMin,
    passes,
    cuttingEfficiencyPct,
    terrainFactorPct,
  });

  const machineHours = area / acresPerHour;
  const daysOnSite = machineHours / hoursPerDay;

  // Mobilization labour is the operator's time, not the machine's: the mulcher
  // is on a trailer and burning nothing. Charging the full machine rate for a
  // float trip is a common and expensive overcorrection in the other
  // direction.
  const mobilizationLabor = trips * mobHours * rate.operator;
  const mobilizationTravel = trips * mobMiles * perMile;
  const mobilizationCost = mobilizationLabor + mobilizationTravel;

  const machineCost = machineHours * rate.total;
  const totalCost = machineCost + mobilizationCost + other;
  const price = totalCost / (1 - margin / 100);

  return {
    acres: area,
    acresPerHour,
    machineHours,
    daysOnSite,
    ratePerHour: rate,
    machineCost,
    mobilizationLabor,
    mobilizationTravel,
    mobilizationCost,
    otherCosts: other,
    totalCost,
    price,
    profit: price - totalCost,
    pricePerAcre: price / area,
    breakEvenPerAcre: totalCost / area,
    pricePerMachineHour: price / machineHours,
    pricePerDay: price / Math.max(daysOnSite, Number.EPSILON),
    mobilizationShareOfPrice: price === 0 ? 0 : mobilizationCost / price,
  };
}

/**
 * The comparison this tool exists to put in front of an operator.
 *
 * A flat dollars-per-acre number is the thing the trade quotes and the thing
 * a customer shops, and it is the same number on every lot. This re-prices
 * the *same acreage* at each density class and reports what that one flat
 * quote earns or loses on each -- which is the question "what do you charge
 * per acre?" cannot be answered honestly without.
 *
 * `quotedPerAcre` is the number the operator is thinking of saying out loud.
 */
export function compareDensities(input, quotedPerAcre) {
  const quoted = requireFinite(quotedPerAcre, 'Quoted price per acre', { min: 0, max: 1000000 });
  const rows = [];
  for (const [id, density] of Object.entries(DENSITY_CLASSES)) {
    const result = priceJob({
      ...input,
      advanceFtPerMin: density.advanceFtPerMin,
      passes: density.passes,
    });
    const revenue = quoted * result.acres;
    rows.push({
      id,
      label: density.label,
      advanceFtPerMin: density.advanceFtPerMin,
      passes: density.passes,
      acresPerHour: result.acresPerHour,
      machineHours: result.machineHours,
      totalCost: result.totalCost,
      breakEvenPerAcre: result.breakEvenPerAcre,
      revenue,
      profit: revenue - result.totalCost,
      marginPct: revenue === 0 ? 0 : ((revenue - result.totalCost) / revenue) * 100,
    });
  }
  return rows;
}

/**
 * Advisory findings. None of these is an error -- every one describes an
 * operational or commercial fact the arithmetic alone would let an operator
 * quote straight past.
 */
export function reviewJob(input, result) {
  const notes = [];

  if (result.mobilizationShareOfPrice >= 0.25) {
    notes.push({
      severity: 'pricing',
      title: 'Mobilization is most of this job',
      detail:
        `Getting there and back costs ${money(result.mobilizationCost)}, which is ` +
        `${(result.mobilizationShareOfPrice * 100).toFixed(0)}% of the ${money(result.price)} price. ` +
        'A per-acre number cannot carry that, because the trailer trip is the same length whether the ' +
        'lot is half an acre or five. Quote this one as a day rate or a minimum charge, or the next ' +
        'small job at the same per-acre figure is the one that loses money.',
    });
  }

  if (result.ratePerHour.teeth <= 0) {
    notes.push({
      severity: 'cost',
      title: 'No allowance for tooth wear',
      detail:
        'Carbide teeth are a consumable, not a repair: a set is consumed over hundreds of hours and ' +
        'faster in sand, rock or dirty stumps. At zero here the quote is carrying none of it, so the ' +
        'set you replace next season comes out of a job that has already been invoiced.',
    });
  } else if (input.toothSetLifeHours >= 600) {
    notes.push({
      severity: 'cost',
      title: 'That tooth life is optimistic for abrasive ground',
      detail:
        `A set lasting ${input.toothSetLifeHours} hours puts tooth wear at ` +
        `${money(result.ratePerHour.teeth)} an hour. That is achievable in clean standing timber and ` +
        'it is not what sandy or rocky sites return. If this site has rock or you cut near grade, ' +
        'halve the life and see what it does to the price before you send it.',
    });
  }

  const ownershipShare = result.ratePerHour.total === 0
    ? 0
    : result.ratePerHour.ownership / result.ratePerHour.total;
  if (ownershipShare >= 0.3) {
    notes.push({
      severity: 'utilisation',
      title: 'The payment, not the work, is setting your hourly cost',
      detail:
        `At ${input.billableHoursPerMonth} billable hours a month the machine carries ` +
        `${money(result.ratePerHour.ownership)} an hour of payment and insurance — ` +
        `${(ownershipShare * 100).toFixed(0)}% of the ${money(result.ratePerHour.total)} it costs to ` +
        'run. That is a utilisation problem wearing a pricing problem\'s clothes: the same payment ' +
        'over twice the hours halves this line. Check the hours figure against last season before ' +
        'you raise the price to cover it.',
    });
  }

  if (result.daysOnSite > 1 && input.mobilizationTrips <= 1) {
    notes.push({
      severity: 'operational',
      title: 'A multi-day job with one trailer trip budgeted',
      detail:
        `This is ${result.daysOnSite.toFixed(1)} days of machine time and one mobilization. That is ` +
        'right only if the machine stays on site overnight — which is a conversation to have with the ' +
        'landowner and with your insurer, not an assumption. If you float it home each evening, put ' +
        'the real number of trips in.',
    });
  }

  if (Number(input.largestStemInches) > Number(input.headRatedStemInches)) {
    notes.push({
      severity: 'scope',
      title: 'Stems larger than the head is rated for',
      detail:
        `You listed stems up to ${input.largestStemInches} in on a head rated to ` +
        `${input.headRatedStemInches} in. Those are a felling job before they are a mulching job, and ` +
        'the time to take them down is not in the production rate above. Price them separately or ' +
        'exclude them in writing — forcing oversized material through the head is how a day is lost ' +
        'to teeth, a belt, or the drum itself.',
    });
  }

  if (Number(input.targetMarginPct) === 0) {
    notes.push({
      severity: 'pricing',
      title: 'This is the walk-away number, not a bid',
      detail:
        `At 0% margin the ${money(result.price)} is exactly what the job costs you to do. It pays the ` +
        'operator, the fuel, the teeth, the reserve and the payment, and it pays nothing for the risk ' +
        'of the estimate being wrong. Use it as the floor you will not go under, not as the number ' +
        'you send.',
    });
  }

  return notes;
}

proposal.mjs.text:
// Turns a finished bid into the document the contractor actually hands the
// customer: a one-page proposal they can print or "Save as PDF" from the
// browser.
//
// Why this exists
// ---------------
// Every bid calculator in this portfolio already ends at a number and a
// plain-text blurb to paste somewhere. That is where the tool stops and the
// contractor's evening starts: retyping the scope into Word, remembering the
// deposit split, guessing how long the price should stand. The proposal is the
// thing that wins or loses the job, and it was the one artifact none of these
// tools produced.
//
// Deliberately NOT a contract
// ---------------------------
// This renders the contractor's own words and numbers into a tidy layout. It
// invents no legal terms, warranties, lien language, or cancellation rights —
// every clause on the page is text the user typed or left blank. A "proposal"
// that shipped boilerplate terms drafted by a calculator would be exactly the
// legal exposure `PRODUCT_PLAYBOOK.md` §5b tells us to avoid, and it would be
// wrong in most jurisdictions anyway.
//
// Privacy
// -------
// `loadCompany` / `saveCompany` persist the *contractor's own* business block
// (their name, phone, licence) so they type it once. The customer's name and
// address are never persisted: that is a third party's personal data sitting on
// someone else's device, and re-typing it per job is cheap. Nothing here
// touches the network.
//
// This file is generic on purpose — no trade, no venture, no storage key baked
// in — so it can be copied verbatim into any calculator in `ventures/`. See the
// venture README for the wiring steps.

/** Fields of the contractor's own business block, in display order. */
export const COMPANY_FIELDS = Object.freeze([
  'companyName', 'companyPhone', 'companyEmail', 'companyLicense', 'companyAddress',
]);

/** Fields describing the customer and the job. Never persisted. */
export const CLIENT_FIELDS = Object.freeze([
  'clientName', 'clientAddress',
]);

/** Commercial terms the contractor controls. */
export const TERM_FIELDS = Object.freeze([
  'depositPercent', 'validDays', 'paymentTerms', 'proposalNotes', 'proposalExclusions',
]);

export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function text(value) {
  return String(value ?? '').trim();
}

function number(value, name, { min = 0, max = Infinity } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (result > max) throw new Error(`${name} must be at most ${max}`);
  return result;
}

/**
 * A figure for the customer's copy.
 *
 * `currency` defaults to `'$'`, which is what every trade in this portfolio
 * quotes in and what all 102 adopters rendered before it was a parameter — so
 * an unchanged caller gets a byte-identical document.
 *
 * It exists because the document is not only a US construction bid. A
 * freelancer quoting a translation names their own currency on the page, and
 * printing `$1,200.00` on a quote the client will pay in euros is not a display
 * nicety: it misstates the price on the one sheet that is meant to settle it.
 * The venture passes whatever its own currency field says.
 *
 * A label is spaced from the figure and a symbol is not — `USD 1,200.00` but
 * `$1,200.00` and `€1,200.00` — decided by whether the currency ends in a
 * letter, which is the only difference a reader would notice between the two.
 *
 * That space is a non-breaking one, written as an escape so it cannot be
 * mistaken for an ordinary space by anyone reading this file or matching
 * against its output. A quote is a printed document with a narrow price
 * column, and "USD" left stranded at the end of a line with its figure on the
 * next is the one place this layout can break in a way the customer sees.
 */
export function money(value, currency = '$') {
  // Sign goes outside the currency symbol: "-$9.24", not "$-9.24". The old
  // spelling put it inside, which is what interpolating a negative straight
  // after a "$" gets you, and it reads as a typo on a document a contractor
  // hands a customer.
  //
  // Round to cents *before* choosing the sign. A delta of two equal figures
  // lands on -0, and a residual like -0.004 rounds to zero at cent precision;
  // both used to print "$-0.00" — a line that is exactly break-even claiming
  // to be down money.
  const cents = Math.round(Math.abs(value) * 100);
  const sign = cents === 0 ? '' : value < 0 ? '-' : '';
  const amount = (cents / 100).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  const unit = text(currency) || '$';
  return `${sign}${unit}${/[A-Za-z]$/.test(unit) ? '\u00a0' : ''}${amount}`;
}

/**
 * Split a textarea into trimmed, non-empty lines. Blank lines are how people
 * space out a scope list; they should not become empty bullets.
 */
export function lines(value) {
  return text(value)
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);
}

/**
 * Fill scope templates from a calculator's result, dropping any line whose
 * figures are not there.
 *
 * Every adoption batch so far has lost a line to the same defect: each
 * calculator names its result differently, `result.doorClass` or `run.material`
 * resolves to `undefined` rather than throwing, and the customer's scope reads
 * "undefined ft of undefined" while every suite stays green. Guessing is the
 * problem; this makes guessing wrong *visible* instead of silent.
 *
 * A template is `'Install {totalLinearFeet} ft of {fenceName}'`, or an object
 * `{ line, when }` where `when` names a field that must be truthy for the line
 * to appear at all.
 *
 * `{ each, line, when }` renders one line **per element** of the array at
 * `each`, with `{field}` reading that element rather than the result root.
 * Half the calculators here price an itemised job — rooms of flooring, gutter
 * runs, trees, kitchen exhaust components — and a homeowner collecting three
 * bids compares the line items, not a total. Without this the only scope such
 * a trade could draft is "Perform the work described above", which the README
 * is explicit is worth less than no proposal at all. `when` is read against
 * the element too, so a row the contractor left at zero stays off the quote:
 *
 * ```json
 * { "each": "rooms", "when": "hours", "line": "{name} — {squareFeet~0} sq ft" }
 * ```
 *
 * Elements are not truncated. Every row the contractor entered is a row they
 * intend to be paid for, and "…and 4 more" on a document someone signs is a
 * dispute waiting to happen.
 *
 * `{field+s}` is that field's plural suffix — `'s'` unless the value is exactly
 * one — so `'{gates} gate{gates+s}'` reads "1 gate" and "3 gates". Without it
 * the obvious thing to write is `'{gates} gate{gates}'`, which prints
 * "3 gate3" on a customer's quote.
 *
 * `{field~2}` rounds to that many decimals and groups thousands, so a derived
 * figure reads "48.89 yd²" and "1,600 sq ft" rather than "48.888888888888886"
 * and "1600". Anything computed — a yardage, a tonnage, a square count — needs
 * it: a quote carrying fifteen decimal places tells the customer the number was
 * produced by a machine that was not being watched.
 *
 * A placeholder that resolves to `undefined`, `null`, `''`,
 * `NaN`, or `Infinity` drops its whole line — a scope with one line missing is
 * a scope the contractor edits, whereas a scope reading `undefined` is one they
 * hand to a customer without noticing.
 *
 * Dropping is not the safety property on its own: an empty scope is also wrong,
 * and `platform/proposal/verify.mjs` fails a page whose default scope comes out
 * empty. Between them, a mis-named field cannot reach a customer quietly.
 *
 * @param {Array<string|{line: string, when?: string, each?: string}>} templates
 * @param {object} values The calculator's result (and anything else to read).
 * @returns {string[]}
 */
export function scopeLines(templates, values) {
  const missing = (value) => value === undefined || value === null || value === ''
    || (typeof value === 'number' && !Number.isFinite(value));

  const readFrom = (scope, path) => String(path).split('.')
    .reduce((node, key) => (node === null || node === undefined ? undefined : node[key]), scope);

  /**
   * One template line against one scope, or `null` if any placeholder in it is
   * missing. Shared by plain lines and `each` rows on purpose: a row must drop
   * on a missing figure by exactly the same rule as a top-level line, or the
   * word "undefined" reaches the customer through whichever path was written
   * second.
   */
  const render = (line, scope) => {
    let complete = true;
    const rendered = line.replace(
      /\{([A-Za-z0-9_.]+?)(?:\+([A-Za-z]+)|~(\d))?\}/g,
      (_match, path, plural, decimals) => {
        const value = readFrom(scope, path);
        if (missing(value)) { complete = false; return ''; }
        if (plural !== undefined) return Number(value) === 1 ? '' : plural;
        if (decimals !== undefined) {
          const number = Number(value);
          if (!Number.isFinite(number)) { complete = false; return ''; }
          return number.toLocaleString('en-US', {
            minimumFractionDigits: 0,
            maximumFractionDigits: Number(decimals),
          });
        }
        return String(value);
      },
    );
    return complete && rendered.trim() ? rendered.trim() : null;
  };

  const filled = [];
  for (const template of templates ?? []) {
    const line = typeof template === 'string' ? template : template?.line;
    if (typeof line !== 'string') continue;
    const each = typeof template === 'object' ? template.each : undefined;

    if (each !== undefined) {
      const rows = readFrom(values, each);
      if (!Array.isArray(rows)) continue;
      for (const row of rows) {
        if (row === null || typeof row !== 'object') continue;
        if (template.when !== undefined && !readFrom(row, template.when)) continue;
        const rendered = render(line, row);
        if (rendered !== null) filled.push(rendered);
      }
      continue;
    }

    if (typeof template === 'object' && template.when !== undefined && !readFrom(values, template.when)) continue;
    const rendered = render(line, values);
    if (rendered !== null) filled.push(rendered);
  }
  return filled;
}

/**
 * `YYYY-MM-DD` plus a whole number of days, in UTC.
 *
 * Local-time date arithmetic silently shifts by a day across a DST boundary,
 * which on a quote-expiry date is a real dispute with a customer.
 */
export function addDays(isoDate, days) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text(isoDate));
  if (!match) throw new Error('Issue date must be YYYY-MM-DD');
  const [, year, month, day] = match;
  const stamp = Date.UTC(Number(year), Number(month) - 1, Number(day));
  if (Number.isNaN(stamp)) throw new Error('Issue date must be a real date');
  return new Date(stamp + number(days, 'Valid days') * 86_400_000)
    .toISOString()
    .slice(0, 10);
}

/** `2026-08-26` → `26 August 2026`. Unambiguous to both US and non-US readers. */
export function formatDate(isoDate) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text(isoDate));
  if (!match) return text(isoDate);
  const [, year, month, day] = match;
  const monthName = new Date(Date.UTC(Number(year), Number(month) - 1, 1))
    .toLocaleDateString('en-US', { month: 'long', timeZone: 'UTC' });
  return `${Number(day)} ${monthName} ${year}`;
}

/**
 * A short, stable reference the contractor and the customer can both quote on
 * the phone. Derived from the issue date and the customer name so that
 * re-printing the same proposal gives the same number, and two proposals
 * written the same day for different customers do not collide.
 */
export function referenceFor(issuedOn, clientName) {
  const compact = text(issuedOn).replaceAll('-', '');
  let hash = 0;
  for (const character of text(clientName).toUpperCase()) {
    hash = (hash * 31 + character.codePointAt(0)) % 1_048_576;
  }
  return `Q-${compact}-${hash.toString(36).toUpperCase().padStart(4, '0').slice(-4)}`;
}

/**
 * Assemble and validate a proposal.
 *
 * Throws on the things that would embarrass the contractor in front of a
 * customer — no business name, no customer name, a zero price, a deposit over
 * 100% — rather than rendering a document with a hole in it.
 */
export function buildProposal(input = {}) {
  const companyName = text(input.companyName);
  if (!companyName) throw new Error('Add your business name before printing a proposal');
  const clientName = text(input.clientName);
  if (!clientName) throw new Error('Add the customer name before printing a proposal');

  const price = number(input.price, 'Price', { min: 0 });
  if (price <= 0) throw new Error('Price a job before printing a proposal');

  const depositPercent = number(input.depositPercent ?? 0, 'Deposit', { min: 0, max: 100 });
  const validDays = number(input.validDays ?? 0, 'Valid days', { min: 0, max: 3650 });
  const issuedOn = text(input.issuedOn) || new Date().toISOString().slice(0, 10);

  // Rounded to cents here, not at display time, and the balance taken as the
  // remainder. The customer adds the two lines up: if the deposit rounds up and
  // the balance rounds down independently, the printed figures miss the printed
  // total by a cent, and the contractor has to explain it on the phone.
  const depositAmount = Math.round(price * depositPercent) / 100;

  return {
    reference: referenceFor(issuedOn, clientName),
    issuedOn,
    validDays,
    validUntil: validDays === 0 ? null : addDays(issuedOn, validDays),
    company: {
      name: companyName,
      phone: text(input.companyPhone),
      email: text(input.companyEmail),
      license: text(input.companyLicense),
      address: text(input.companyAddress),
    },
    client: {
      name: clientName,
      address: text(input.clientAddress),
    },
    job: {
      title: text(input.jobTitle) || 'Proposed work',
      scope: lines(input.scope),
      exclusions: lines(input.proposalExclusions),
      notes: text(input.proposalNotes),
    },
    pricing: {
      price,
      depositPercent,
      depositAmount,
      balanceAmount: price - depositAmount,
      paymentTerms: text(input.paymentTerms),
    },
  };
}

function block(title, body) {
  return body ? `<div class="pr-block"><h3>${escapeHtml(title)}</h3>${body}</div>` : '';
}

function list(items) {
  return items.length === 0
    ? ''
    : `<ul>${items.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul>`;
}

function paragraphs(value) {
  return value ? `<p>${escapeHtml(value).replaceAll('\n', '<br>')}</p>` : '';
}

/**
 * Render the proposal as the HTML that goes inside the page's print container.
 *
 * Returns a fragment, not a whole document: the page owns the print stylesheet,
 * so the same markup is what the contractor previews on screen and what comes
 * out of the printer. A separate print-only document is how the two drift.
 *
 * @param {ReturnType<typeof buildProposal>} proposal
 * @param {object} [options]
 * @param {string} [options.disclaimer] Sentence to print in the footer. The
 *   caller supplies it so each trade can name its own regulator and scope.
 * @param {string} [options.currency] Prefix for every figure on the sheet.
 *   Defaults to `'$'`; see `money`.
 */
export function renderProposalHtml(proposal, { disclaimer = '', currency = '$' } = {}) {
  const { company, client, job, pricing } = proposal;
  const amount = (value) => money(value, currency);

  const contact = [company.phone, company.email, company.address]
    .filter(Boolean)
    .map((line) => `<span>${escapeHtml(line)}</span>`)
    .join('');

  const validity = proposal.validUntil
    ? `<p class="pr-validity">This price is held until <strong>${escapeHtml(formatDate(proposal.validUntil))}</strong> (${proposal.validDays} days from issue).</p>`
    : '';

  const depositRow = pricing.depositPercent > 0
    ? `<tr><td>Deposit due on acceptance (${pricing.depositPercent}%)</td><td>${amount(pricing.depositAmount)}</td></tr>
       <tr><td>Balance due on completion</td><td>${amount(pricing.balanceAmount)}</td></tr>`
    : '';

  return `
    <article class="pr-doc">
      <header class="pr-head">
        <div>
          <h2>${escapeHtml(company.name)}</h2>
          <div class="pr-contact">${contact}</div>
          ${company.license ? `<p class="pr-license">Licence ${escapeHtml(company.license)}</p>` : ''}
        </div>
        <div class="pr-meta">
          <p class="pr-kicker">Proposal</p>
          <p><strong>${escapeHtml(proposal.reference)}</strong></p>
          <p>${escapeHtml(formatDate(proposal.issuedOn))}</p>
        </div>
      </header>

      <div class="pr-parties">
        <div class="pr-block"><h3>Prepared for</h3>
          <p><strong>${escapeHtml(client.name)}</strong></p>
          ${paragraphs(client.address)}
        </div>
        <div class="pr-block"><h3>Work</h3>
          <p><strong>${escapeHtml(job.title)}</strong></p>
        </div>
      </div>

      ${block('Scope of work', list(job.scope))}
      ${block('Not included', list(job.exclusions))}
      ${block('Notes', paragraphs(job.notes))}

      <table class="pr-price">
        <tbody>
          <tr class="pr-total"><td>Total price</td><td>${amount(pricing.price)}</td></tr>
          ${depositRow}
        </tbody>
      </table>
      ${validity}
      ${block('Payment terms', paragraphs(pricing.paymentTerms))}

      <div class="pr-sign">
        <div><span class="pr-rule"></span><p>Customer signature</p></div>
        <div><span class="pr-rule"></span><p>Date</p></div>
      </div>

      ${disclaimer ? `<p class="pr-disclaimer">${escapeHtml(disclaimer)}</p>` : ''}
    </article>
  `;
}

/**
 * Read the saved business block. A corrupt or absent entry is an empty block,
 * never an exception: a broken localStorage value must not stop someone
 * pricing a job.
 */
export function loadCompany(storage, key) {
  try {
    const saved = JSON.parse(storage?.getItem(key) || '{}');
    return Object.fromEntries(
      COMPANY_FIELDS.map((field) => [field, text(saved?.[field])]),
    );
  } catch {
    return Object.fromEntries(COMPANY_FIELDS.map((field) => [field, '']));
  }
}

/**
 * Persist the business block only. `CLIENT_FIELDS` are excluded by
 * construction, not by the caller remembering to strip them.
 */
export function saveCompany(storage, key, values = {}) {
  const payload = Object.fromEntries(
    COMPANY_FIELDS.map((field) => [field, text(values[field])]),
  );
  try {
    storage?.setItem(key, JSON.stringify(payload));
  } catch {
    // A full or disabled localStorage is not worth an error in front of the
    // customer; the proposal still prints, it just will not be pre-filled next
    // time.
  }
  return payload;
}

export function forgetCompany(storage, key) {
  try {
    storage?.removeItem(key);
  } catch {
    // Same reasoning as saveCompany.
  }
}

share.mjs.text:
// Shareable job link for the forestry mulching bid calculator.
//
// This tool is priced by one operator alone, but the job it prices rarely
// stays with one person: a partner runs the numbers on the same lot, a crew
// lead is told the machine hours and mobilization plan, or an operator wants
// a second read on their own assumptions before quoting. A downloaded
// worksheet is a dead end for that conversation -- the other side can only
// read a number somebody else produced, not change the tooth life or the
// billable hours a month and watch the price move. A link fixes that: the
// recipient lands on the same job, already filled in, editable field by
// field.
//
// The payload rides in the URL *fragment*, which browsers never send to a
// server, so the "nothing leaves your browser" promise this page already
// makes survives the feature. Anyone holding the link can read the figures,
// which is the same exposure as forwarding the downloaded worksheet.
//
// The transform is pure: no DOM, no storage, no network.

import { DENSITY_CLASSES } from './calc.mjs';

/**
 * Every numeric field the job form collects. Same ids `index.html` declares
 * on its `<input type="number">` elements and the same set its `NUMERIC`
 * array reads for validation -- if a field is added to the form and not
 * here, a share link silently drops it, and the recipient prices a
 * different job than the sender did with nothing on screen to say so.
 */
export const FIELD_IDS = Object.freeze([
  'acres', 'largestStemInches', 'terrainFactorPct', 'headWidthFt', 'headRatedStemInches',
  'advanceFtPerMin', 'passes', 'cuttingEfficiencyPct', 'workHoursPerDay',
  'operatorWagePerHour', 'fuelGallonsPerHour', 'fuelPricePerGallon', 'toothSetCost',
  'toothSetLifeHours', 'maintenancePerHour', 'machinePaymentMonthly', 'insuranceAnnual',
  'billableHoursPerMonth', 'mobilizationTrips', 'mobilizationHoursEach',
  'mobilizationMilesEach', 'truckCostPerMile', 'otherCosts', 'targetMarginPct',
  'quotedPerAcre',
]);

/**
 * The one non-numeric field: which density preset is selected. Carrying it
 * alongside the numbers it wrote (`advanceFtPerMin`, `passes`) means the
 * recipient's dropdown shows the same preset the sender picked, rather than
 * silently reverting to "My own numbers..." with the right figures but the
 * wrong label -- which matters because choosing a different preset on the
 * recipient's page overwrites those two fields.
 */
export const DENSITY_FIELD_ID = 'density';

/**
 * The proposal panel's own terms (`platform/proposal/adopt.mjs`): the
 * deposit, how long the price is held, and the three blocks of prose a
 * contractor writes once and reuses. A shared job link that carries the
 * price but not these opens the recipient on this venture's own defaults
 * (30% / 30 days) under a headline figure that matches the sender's to the
 * cent -- two people reading one price and different money on acceptance,
 * with nothing on screen to say so. See `platform/proposal/term-ids.test.mjs`
 * for the incident this list exists to prevent.
 */
export const PROPOSAL_TERM_NUMBERS = Object.freeze(['depositPercent', 'validDays']);
export const PROPOSAL_TERM_TEXT = Object.freeze(['paymentTerms', 'proposalNotes', 'proposalExclusions']);

/** A job figure: finite. Blank, missing or unparsable means "not entered". */
function jobNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  const result = Number(value);
  return Number.isFinite(result) ? result : null;
}

/** A proposal-term number, bounded exactly as its own `<input>` is. */
function termNumber(value, { min, max }) {
  const result = jobNumber(value);
  if (result === null || result < min || result > max) return null;
  return result;
}

/** Free text the contractor typed. Empty means "left blank", not "unset". */
function termText(value) {
  return typeof value === 'string' ? value : null;
}

/** A density value the page's own `<select>` actually offers. */
function validDensity(value) {
  if (value === 'custom' || Object.hasOwn(DENSITY_CLASSES, value)) return value;
  return null;
}

/**
 * Encode the page's current inputs as a URL fragment payload.
 *
 * Blank or unusable figures are omitted rather than sent as empty strings,
 * so the recipient keeps their own default for anything the sender never
 * filled in -- each field here is independently visible on the page, unlike
 * a grouped clause, so there is nothing to bias by dropping one on its own.
 */
export function encodeInputs(inputs) {
  const params = new URLSearchParams();
  for (const id of FIELD_IDS) {
    const value = jobNumber(inputs?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  const density = validDensity(inputs?.[DENSITY_FIELD_ID]);
  if (density !== null) params.set(DENSITY_FIELD_ID, density);

  const deposit = termNumber(inputs?.depositPercent, { min: 0, max: 100 });
  if (deposit !== null) params.set('depositPercent', String(deposit));
  const validDays = termNumber(inputs?.validDays, { min: 0, max: 365 });
  if (validDays !== null) params.set('validDays', String(validDays));
  for (const id of PROPOSAL_TERM_TEXT) {
    const text = termText(inputs?.[id]);
    if (text) params.set(id, text);
  }
  return params.toString();
}

/**
 * Read a fragment (or query string) back into an input map.
 *
 * Nothing here throws. A link truncated by a messaging app, hand-edited, or
 * carrying a key this page does not know should open the calculator on
 * whatever survived, not on an error page -- the recipient can always
 * retype the one field that did not make it, and cannot recover from a
 * blank screen. A figure that fails to parse is dropped on its own; it does
 * not take any other field down with it.
 */
export function decodeInputs(source) {
  if (typeof source !== 'string') return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ''));
  const inputs = {};
  for (const id of FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = jobNumber(params.get(id));
    if (value !== null) inputs[id] = value;
  }
  if (params.has(DENSITY_FIELD_ID)) {
    const density = validDensity(params.get(DENSITY_FIELD_ID));
    if (density !== null) inputs[DENSITY_FIELD_ID] = density;
  }

  if (params.has('depositPercent')) {
    const deposit = termNumber(params.get('depositPercent'), { min: 0, max: 100 });
    if (deposit !== null) inputs.depositPercent = deposit;
  }
  if (params.has('validDays')) {
    const validDays = termNumber(params.get('validDays'), { min: 0, max: 365 });
    if (validDays !== null) inputs.validDays = validDays;
  }
  for (const id of PROPOSAL_TERM_TEXT) {
    if (params.has(id)) inputs[id] = params.get(id);
  }
  return inputs;
}

/**
 * Build the shareable URL for a page location and an input set.
 *
 * Any existing query string is preserved and the fragment replaced, so a
 * link copied from a page that was itself opened from a link does not
 * accumulate payloads.
 */
export function shareUrl(location, inputs) {
  const origin = location?.origin ?? '';
  const pathname = location?.pathname ?? '';
  const search = location?.search ?? '';
  return `${origin}${pathname}${search}#${encodeInputs(inputs)}`;
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser.
//
// It never stores an acreage, a location, a customer, an hourly cost, a machine
// payment or any figure the worksheet produces. What a one-machine operation
// pays for fuel, what it owes on the machine, how many hours a month it really
// bills and the margin it quotes at are the commercially sensitive core of that
// business -- the kind of thing the operator bidding against them would pay for
// -- so nothing about a job is written anywhere but the page in front of the
// person typing it.

const STORAGE_KEY = 'forestry-mulching-bid-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'job_priced') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page pricing a job.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
